tool_input.command:
mkdir -p migrations/down && cat > migrations/002_product_discount.sql <<'EOF'
-- Runs as one implicit transaction, so SET LOCAL scopes the timeout to this file.
set local lock_timeout = '5s';
alter table products add column discount_percent integer not null default 0;
-- NOT VALID so the table isn't scanned under lock; validated in 003.
alter table products add constraint products_discount_percent_range
  check (discount_percent between 0 and 100) not valid;
EOF
cat > migrations/003_product_discount_validate.sql <<'EOF'
alter table products validate constraint products_discount_percent_range;
EOF
cat > migrations/down/002_product_discount.sql <<'EOF'
set local lock_timeout = '5s';
alter table products drop constraint products_discount_percent_range;
alter table products drop column discount_percent;
EOF
cat > migrations/down/003_product_discount_validate.sql <<'EOF'
-- Validation can't be undone; the constraint stays (dropped by down/002).
select 1;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('"select id, name, price_cents, stock from products order by id"','"select id, name, price_cents, stock, discount_percent from products order by id"')
s=s.replace('''  app.get("/orders"''','''  app.patch("/products/:id", async (req, res) => {
    if (res.locals.user.role !== "admin") return sendError(res, 403, "forbidden", "Admins only");
    const id = Number(req.params.id);
    if (!Number.isSafeInteger(id) || id < 1 || id > 2147483647) {
      return sendError(res, 400, "invalid_id", "Product id must be a positive integer");
    }
    const discount = req.body?.discountPercent;
    if (!Number.isInteger(discount) || discount < 0 || discount > 100) {
      return sendError(res, 400, "invalid_discount", "discountPercent must be an integer from 0 to 100");
    }
    const { rows } = await pool.query(
      "update products set discount_percent = $1 where id = $2 returning id, name, price_cents, stock, discount_percent",
      [discount, id],
    );
    if (rows.length === 0) return sendError(res, 404, "not_found", "Product not found");
    res.json(rows[0]);
  });

  app.get("/orders"''',1)
open(p,'w').write(s)
p='postman/shop-api.postman_collection.json'
s=open(p).read()
s=s.replace('''"{{baseUrl}}/products" } },''','''"{{baseUrl}}/products" } },
    {
      "name": "Set product discount (admin)",
      "request": {
        "method": "PATCH",
        "auth": { "type": "bearer", "bearer": [{ "key": "token", "value": "admin-token", "type": "string" }] },
        "header": [{ "key": "Content-Type", "value": "application/json" }],
        "body": { "mode": "raw", "raw": "{ \\"discountPercent\\": 20 }" },
        "url": "{{baseUrl}}/products/1"
      }
    },''',1)
open(p,'w').write(s)
EOF
sed -n 1,52p test/app.test.ts; tail -15 test/app.test.ts

U=postgres://postgres:postgres@localhost:5433/run_product_discount_with_5_20261104211820_5454; P="psql $U -v ON_ERROR_STOP=1 -qtA"; 
$P -c "select column_name from information_schema.columns where table_name='products' and column_name='discount_percent'" ; 
$P -1 -f migrations/down/003_product_discount_validate.sql >/dev/null && $P -1 -f migrations/down/002_product_discount.sql && $P -c "select count(*) from information_schema.columns where table_name='products' and column_name='discount_percent'" && $P -c "delete from schema_migrations where name like '00[23]%'" && DATABASE_URL=$U pnpm migrate && $P -c "select id, discount_percent from products order by id"
